package com.aaliyun.leadnews.ai;import com.aaliyun.leadnews.ai.support.StructuredOutputParser;import com.aaliyun.leadnews.model.ai.*;import jakarta.validation.Validation;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;
class StructuredOutputTest {@Test void parsesMarkdownFence(){try(var f=Validation.buildDefaultValidatorFactory()){var p=new StructuredOutputParser(f.getValidator());var r=p.parse("```json\n{\"decision\":\"REVIEW\",\"riskLevel\":\"LOW\",\"reason\":\"test\",\"confidence\":0.8,\"riskTags\":[]}\n```",StructuredModerationResult.class);assertThat(r.decision()).isEqualTo(ModerationDecision.REVIEW);}}}
